def standardize_region(df):
    out = df.copy()
    out["region"] = out["region"].str.strip().str.title()
    return out

def add_revenue(df):
    out = df.copy()
    out["revenue"] = out["quantity"] * out["unit_price"]
    return out

def clean_orders(raw):
    return raw.drop_duplicates(subset="order_id").pipe(standardize_region).pipe(add_revenue)
